(7037403, 1069474, 44882, '<td valign="top">I wish at least one of them had looked at you.</td>', 'I wish at least one of them had looked at you.', '2013-05-15 08:31:20.000000', NULL, 1),
(7037425, 1068908, 158576, '<td valign="top">Good composition, nice depth of field, but needs more contrast. Unfortunately, it''s too easy to photograph homeless people, so that it''s become cliché shot in street photography. Although it''s a technically competent photo, I have to take points away for content.</td>', 'Good composition, nice depth of field, but needs more contrast. Unfortunately, it''s too easy to photograph homeless people, so that it''s become cliché shot in street photography. Although it''s a technically competent photo, I have to take points away for content.', '2013-05-15 09:24:22.000000', NULL, 1),
(7037427, 1068976, 158576, '<td valign="top">The motion blur on both men''s right foot and the left man''s hand is distracting.</td>', 'The motion blur on both men''s right foot and the left man''s hand is distracting.', '2013-05-15 09:27:07.000000', NULL, 1),
(7037432, 1069462, 54446, '<td valign="top">I like your monochrome toning.  This is a quality conversion.  You aren''t dealing with sophisticated voters, so you may get slammed for the risk-taking.  But, you did a nice job!  8</td>', 'I like your monochrome toning.  This is a quality conversion.  You aren''t dealing with sophisticated voters, so you may get slammed for the risk-taking.  But, you did a nice job!  8', '2013-05-15 09:32:39.000000', NULL, 1),
(7037434, 1068969, 158576, '<td valign="top">Nice shot. Catching the reflections makes it so much more interesting, but the strong backlight washes out the girls a bit. Exposing for the light coming from outside would have silhouetted the girls making a better photo.</td>', 'Nice shot. Catching the reflections makes it so much more interesting, but the strong backlight washes out the girls a bit. Exposing for the light coming from outside would have silhouetted the girls making a better photo.', '2013-05-15 09:32:57.000000', NULL, 1),
(7037437, 1069428, 54446, '<td valign="top">I think you are too far away from the guys.  Too much building.  Not enough information on the people.</td>', 'I think you are too far away from the guys.  Too much building.  Not enough information on the people.', '2013-05-15 09:34:54.000000', NULL, 1),
(7037438, 1069325, 158576, '<td valign="top">Great shot. The contrast really works, bringing out the details of this musician. The "leading line" made by the guitar case is almost a distraction though.</td>', 'Great shot. The contrast really works, bringing out the details of this musician. The "leading line" made by the guitar case is almost a distraction though.', '2013-05-15 09:35:48.000000', NULL, 1),
(7037439, 1069278, 158576, '<td valign="top">You caught a decisive moment!</td>', 'You caught a decisive moment!', '2013-05-15 09:36:18.000000', NULL, 1),
(7037442, 1069426, 54446, '<td valign="top">Needs more elements of interest.</td>', 'Needs more elements of interest.', '2013-05-15 09:37:11.000000', NULL, 1),
