(7037448, 1069373, 54446, '<td valign="top">Interesting to view.  Pit bull and owners at outside restaurant.  Well seen and captured.  9</td>', 'Interesting to view.  Pit bull and owners at outside restaurant.  Well seen and captured.  9', '2013-05-15 09:39:53.000000', NULL, 1),
(7037450, 1069012, 158576, '<td valign="top">Nice shot, but would have been better if you caught more than one pin in the air. Because two pins are still in his hands, the motion blur doesn''t really work for me.</td>', 'Nice shot, but would have been better if you caught more than one pin in the air. Because two pins are still in his hands, the motion blur doesn''t really work for me.', '2013-05-15 09:42:39.000000', NULL, 1),
(7037452, 1069352, 158576, '<td valign="top">The scene is good, but the exposure causes the eye to be drawn to the brightly lit wall so the girl and her balloons became lost.</td>', 'The scene is good, but the exposure causes the eye to be drawn to the brightly lit wall so the girl and her balloons became lost.', '2013-05-15 09:44:12.000000', NULL, 1),
(7037454, 1069419, 158576, '<td valign="top">If only the street sign wasn''t cutting the man in half. The 2 "gawkers" are a distraction. Would have been better if you could have captured the shot before they notice you taking the photo.</td>', 'If only the street sign wasn''t cutting the man in half. The 2 "gawkers" are a distraction. Would have been better if you could have captured the shot before they notice you taking the photo.', '2013-05-15 09:46:01.000000', NULL, 1),
