(7037602, 1069352, 23484, '<td valign="top">The lighting is really cool. Neat reflections.</td>', 'The lighting is really cool. Neat reflections.', '2013-05-15 11:43:14.000000', NULL, 1),
(7037603, 1069462, 23484, '<td valign="top">Excellent angle and perspective. The color is definitely different.</td>', 'Excellent angle and perspective. The color is definitely different.', '2013-05-15 11:44:06.000000', NULL, 1),
(7037604, 1069286, 23484, '<td valign="top">Excellent perspective. That is an interesting shoe.</td>', 'Excellent perspective. That is an interesting shoe.', '2013-05-15 11:45:24.000000', NULL, 1),
