(7037609, 1069193, 23484, '<td valign="top">This is fantastic. Love the blown out look.</td>', 'This is fantastic. Love the blown out look.', '2013-05-15 11:47:39.000000', NULL, 1),
(7037611, 1069367, 158576, '<td valign="top">Interesting POV. Makes me wonder if they are watching the mothership land. :)</td>', 'Interesting POV. Makes me wonder if they are watching the mothership land. :)', '2013-05-15 11:48:00.000000', NULL, 1),
(7037612, 1068996, 23484, '<td valign="top">Looks like he needs his hair cut fixed.</td>', 'Looks like he needs his hair cut fixed.', '2013-05-15 11:48:38.000000', NULL, 1),
(7037615, 1069193, 158576, '<td valign="top">The blown out background is a distraction, but it doesn''t bother me as much as the POV and the fact that she''s centered right in the middle of the shot.</td>', 'The blown out background is a distraction, but it doesn''t bother me as much as the POV and the fact that she''s centered right in the middle of the shot.', '2013-05-15 11:52:44.000000', NULL, 1),
(7037616, 1069402, 158576, '<td valign="top">I like the POV, and the use of the flowers to frame the people, but the flowers take up way to much of the shot and draw my attention to them instead of to the people.</td>', 'I like the POV, and the use of the flowers to frame the people, but the flowers take up way to much of the shot and draw my attention to them instead of to the people.', '2013-05-15 11:55:01.000000', NULL, 1),
