(7039986, 1069469, 59740, '<td valign="top">Nice scene. I find the live person is a little too dark and too centered.</td>', 'Nice scene. I find the live person is a little too dark and too centered.', '2013-05-19 19:24:49.000000', NULL, 1),
(7039987, 1069432, 59740, '<td valign="top">Unfortunately the flare makes the person almost invisible. I don''t get the point?</td>', 'Unfortunately the flare makes the person almost invisible. I don''t get the point?', '2013-05-19 19:25:56.000000', NULL, 1),
(7039988, 1069474, 59740, '<td valign="top">The boys would be much more captivating if I could see what they are looking at.</td>', 'The boys would be much more captivating if I could see what they are looking at.', '2013-05-19 19:26:34.000000', NULL, 1),
(7039989, 1068953, 59740, '<td valign="top">Nice try. A little slower shutter speed would but the veil out of focus so it would look like it''s blowing and would keep the dress from being overexposed.</td>', 'Nice try. A little slower shutter speed would but the veil out of focus so it would look like it''s blowing and would keep the dress from being overexposed.', '2013-05-19 19:28:00.000000', NULL, 1),
(7039991, 1069315, 59740, '<td valign="top">Interesting shot. It''s very confusing though. I can''t tell from what angle the photo is taken. it almost looks like the person is in midair.</td>', 'Interesting shot. It''s very confusing though. I can''t tell from what angle the photo is taken. it almost looks like the person is in midair.', '2013-05-19 19:29:42.000000', NULL, 1),
(7039992, 1069338, 59740, '<td valign="top">Nice reflection. I would like to see the person''s face.</td>', 'Nice reflection. I would like to see the person''s face.', '2013-05-19 19:30:24.000000', NULL, 1),
(7039994, 1069303, 59740, '<td valign="top">Mysterious. I''m not sure what''s going on but I like it.</td>', 'Mysterious. I''m not sure what''s going on but I like it.', '2013-05-19 19:31:10.000000', NULL, 1),
(7039995, 1069307, 59740, '<td valign="top">Faces are so much more interesting than backs.</td>', 'Faces are so much more interesting than backs.', '2013-05-19 19:31:50.000000', NULL, 1),
(7039996, 1069337, 59740, '<td valign="top">Great capture. Mysterious.</td>', 'Great capture. Mysterious.', '2013-05-19 19:32:49.000000', NULL, 1),
